if (window.location.protocol === 'http:' && ['nyfholdings.ca', 'www.nyfholdings.ca'].includes(window.location.hostname)) window.location.replace(`https://${window.location.host}${window.location.pathname}${window.location.search}${window.location.hash}`);
const operationsFragments=new Set(['#crm','#command','#daily','#activity','#intelligence','#evidence','#financial']);if(operationsFragments.has(window.location.hash.toLowerCase())&&window.location.pathname==='/')window.location.replace(`/operations/${window.location.hash}`);
const menuButton=document.querySelector('[data-menu]'),navigation=document.querySelector('[data-nav]');function closeMenu(){if(!menuButton||!navigation)return;menuButton.setAttribute('aria-expanded','false');navigation.classList.remove('is-open')}if(menuButton&&navigation){menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')==='true';menuButton.setAttribute('aria-expanded',String(!open));navigation.classList.toggle('is-open',!open)});navigation.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});window.addEventListener('resize',()=>{if(window.innerWidth>900)closeMenu()})}document.querySelectorAll('[data-year]').forEach(n=>n.textContent=new Date().getFullYear());
const revealItems=document.querySelectorAll('[data-reveal]');if('IntersectionObserver'in window&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');o.unobserve(e.target)}}),{threshold:.12});revealItems.forEach(i=>o.observe(i))}else revealItems.forEach(i=>i.classList.add('is-visible'));
const searchForm=document.querySelector('[data-search-form]'),searchInput=document.querySelector('[data-search-input]'),searchResults=document.querySelector('[data-search-results]'),searchStatus=document.querySelector('[data-search-status]');if(searchForm&&searchInput&&searchResults&&searchStatus){const normal=v=>String(v||'').toLowerCase().normalize('NFKD').replace(/[^a-z0-9\s-]/g,' '),makeResult=item=>{const link=document.createElement('a');link.className='search-result';link.href=item.url;const section=document.createElement('span');section.className='result-section';section.textContent=item.section;const copy=document.createElement('div'),title=document.createElement('h2'),description=document.createElement('p');title.textContent=item.title;description.textContent=item.description;copy.append(title,description);const arrow=document.createElement('span');arrow.className='arrow';arrow.setAttribute('aria-hidden','true');arrow.textContent='↗';link.append(section,copy,arrow);return link};fetch('/search-index.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error();return r.json()}).then(index=>{const render=raw=>{const q=normal(raw).trim(),tokens=q.split(/\s+/).filter(Boolean),ranked=index.map(item=>{const t=normal(item.title),s=normal(item.section),d=normal(item.description),k=normal((item.keywords||[]).join(' ')),score=tokens.reduce((x,z)=>x+(t.includes(z)?12:0)+(s.includes(z)?7:0)+(k.includes(z)?5:0)+(d.includes(z)?3:0),0),matches=!tokens.length||tokens.every(z=>`${t} ${s} ${d} ${k}`.includes(z));return{item,score,matches}}).filter(x=>x.matches).sort((a,b)=>b.score-a.score||a.item.title.localeCompare(b.item.title));searchResults.replaceChildren();ranked.forEach(x=>searchResults.append(makeResult(x.item)));searchStatus.textContent=q?`${ranked.length} public results for “${raw.trim()}”.`:`${ranked.length} public pages in the index.`};const initial=new URLSearchParams(location.search).get('q')||'';searchInput.value=initial;render(initial);searchForm.addEventListener('submit',e=>{e.preventDefault();render(searchInput.value)});searchInput.addEventListener('input',()=>render(searchInput.value))}).catch(()=>searchStatus.textContent='The public directory is shown below; live filtering is temporarily unavailable.')}

document.querySelectorAll('[data-newsletter-form]').forEach(form=>{const status=form.querySelector('[data-newsletter-status]')||document.querySelector('[data-newsletter-status]');if(!status)return;form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button[type="submit"]'),fd=new FormData(form),campaign=fd.get('campaign')||form.dataset.campaign||'dispatch',source=fd.get('source')||location.pathname;const payload={name:fd.get('name'),email:fd.get('email'),website:fd.get('website'),consent:fd.get('consent')==='yes',campaign,source};button.disabled=true;status.textContent=campaign==='deregulation'?'Unlocking the campaign…':'Adding you to the Dispatch…';status.classList.remove('is-error','is-success');try{const response=await fetch('https://nyf-east-corner.nyfh.chatgpt.site/api/public/newsletter',{method:'POST',mode:'cors',credentials:'omit',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'The list could not accept that address right now.');form.reset();status.textContent=data.message||(campaign==='deregulation'?'Campaign access recorded. Check your inbox for the full reader path.':"You're on the Dispatch list.");status.classList.add('is-success')}catch(error){status.textContent=error instanceof Error?error.message:'The list could not accept that address right now.';status.classList.add('is-error')}finally{button.disabled=false}})});
